<div class="stats-grid premium-stats"><?php foreach(['patients'=>['Pacientes registrados','users','Activos registrados en el período','/admin/patients'],'appointments'=>['Citas del período','calendar','Por fecha de atención','/admin/appointments?date='.$f['from'].'&mode=month'],'treatments'=>['Tratamientos realizados','tooth','Procedimientos completados','/admin/treatments'],'income'=>['Ingresos vigentes','wallet','Cobros del período sin anular','/admin/payments']] as $key=>[$name,$i,$note,$href]):if(!isset($stats[$key]))continue;$enabled=can(['patients'=>'patients','appointments'=>'appointments','treatments'=>'treatments','income'=>'payments'][$key]); ?><article class="stat metric-card <?= $key==='income' ? 'metric-income':'' ?>" data-reveal><div class="between"><span><?= $name ?></span><span class="stat-icon <?= e($key) ?>"><?= icon($i,22) ?></span></div><strong data-count="<?= e($stats[$key]) ?>" data-count-key="<?= $key ?>" data-money="<?= $key==='income' ? 'true':'false' ?>"><?= $key==='income' ? money($stats[$key]):(int)$stats[$key] ?></strong><div class="metric-bottom"><small><?= $note ?></small><?php if($enabled): ?><a href="<?= e(url($href)) ?>" class="metric-link" aria-label="Abrir <?= e($name) ?>"><?= icon('arrow',17) ?></a><?php endif; ?></div></article><?php endforeach; ?></div>
<?php if($allowed['finance']||$allowed['appointments']||$allowed['treatments']): ?><div class="dashboard-charts"><section class="panel trend-panel" data-reveal><div class="panel-heading"><div><span class="eyebrow">EVOLUCIÓN DEL CONSULTORIO</span><h2>El ritmo de tu clínica</h2><p><?= e($f['from']) ?> — <?= e($f['to']) ?></p></div><label class="metric-picker">Mostrar<select id="trend-metric"><?php foreach(['income'=>'Ingresos ($)','payments'=>'Pagos recibidos','appointments'=>'Citas agendadas','treatments'=>'Tratamientos realizados'] as $key=>$name):if((in_array($key,['income','payments'])&&!$allowed['finance'])||($key==='appointments'&&!$allowed['appointments'])||($key==='treatments'&&!$allowed['treatments']))continue; ?><option value="<?= $key ?>"<?= selected($f['metric'],$key) ?>><?= $name ?></option><?php endforeach; ?></select></label></div><div class="trend-visual"><canvas id="live-trend-chart" role="img" aria-label="Evolución diaria del período seleccionado" data-chart="<?= e(json_encode($chart)) ?>" data-metric="<?= e($f['metric']) ?>"></canvas></div><div class="trend-inspect"><output id="trend-value">Selecciona una fecha para consultar el valor.</output><label>Explorar fechas<input id="trend-date" type="range" min="0" max="<?= count($chart)-1 ?>" value="<?= count($chart)-1 ?>" aria-label="Día de la gráfica"></label></div><details class="chart-data"><summary>Ver tabla accesible de la gráfica</summary><div class="table-wrap" tabindex="0" role="region" aria-label="Datos diarios"><table><thead><tr><th>Fecha</th><?php if($allowed['finance']): ?><th>Ingresos</th><th>Pagos</th><?php endif; ?><?php if($allowed['appointments']): ?><th>Citas</th><?php endif; ?><?php if($allowed['treatments']): ?><th>Tratamientos</th><?php endif; ?></tr></thead><tbody><?php foreach($chart as $c): ?><tr><td><?= e($c['day']) ?></td><?php if($allowed['finance']): ?><td><?= money($c['income']) ?></td><td><?= $c['payments'] ?></td><?php endif; ?><?php if($allowed['appointments']): ?><td><?= $c['appointments'] ?></td><?php endif; ?><?php if($allowed['treatments']): ?><td><?= $c['treatments'] ?></td><?php endif; ?></tr><?php endforeach; ?></tbody></table></div></details></section><section class="panel distribution-panel" data-reveal><div class="panel-heading"><div><span class="eyebrow">PANORAMA DE LA AGENDA</span><h2>Cada visita cuenta</h2><p>Mismo período · fecha de atención</p></div></div><?php if($allowed['appointments']): ?><div class="donut-wrap"><canvas id="status-chart" width="180" height="180" role="img" aria-label="Citas por estado" data-chart="<?= e(json_encode($distribution)) ?>"></canvas></div><div class="status-legend"><?php foreach($distribution as $s): ?><div><?= badge($s['status']) ?><strong><?= (int)$s['total'] ?></strong></div><?php endforeach; ?></div><?php if(!$distribution): ?><p class="empty">No hay citas en este período. Cambia las fechas o registra una visita.</p><?php endif; ?><?php else: ?><div class="empty"><?= icon('shield',35) ?><p>La agenda está reservada al personal autorizado.</p></div><?php endif; ?></section></div><?php endif; ?>
